async function performStep(stepName, action) {
  const stepTimer = new Timer();
  stepTimer.start();
  try {
    await action();
    const duration = stepTimer.stop();
    testResults.push({
      module: "Dashboard",
      testCase: stepName,
      time: duration,
      clicks: clickCountObj.count,
      steps: stepName,
      status: "Pass",
    });
  } catch (err) {
    const duration = stepTimer.stop();
    testResults.push({
      module: "Dashboard",
      testCase: stepName,
      time: duration,
      clicks: clickCountObj.count,
      steps: stepName + " | Error: " + err.message,
      status: "Fail",
    });
    throw err;
  }
}
